<div class="settings-layout security-layout"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Authentication policy</span><h2>Password and session controls</h2></div></header><form class="settings-form form-grid" action="<?= h(app_url('action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_security_settings"><input type="hidden" name="return_to" value="admin/security.php"><label><span>Minimum password length</span><input type="number" min="8" name="password_min_length" value="<?= (int)$settings['password_min_length'] ?>" min="8" max="128" required></label><label><span>Login-attempt limit</span><input type="number" min="3" name="login_attempt_limit" value="<?= (int)$settings['login_attempt_limit'] ?>" min="3" max="20" required></label><label><span>Lockout duration (minutes)</span><input type="number" min="5" name="lockout_minutes" value="<?= (int)$settings['lockout_minutes'] ?>" min="5" max="1440" required></label><label><span>Session lifetime (minutes)</span><input type="number" min="15" name="session_lifetime" value="<?= (int)$settings['session_lifetime'] ?>" min="15" max="1440" required></label><label class="span-2"><span>Password-reset lifetime (minutes)</span><input type="number" min="15" name="password_reset_lifetime" value="<?= (int)$settings['password_reset_lifetime'] ?>" min="15" max="1440" required></label><label class="span-2 toggle-row"><span><strong>Require mixed case</strong><small>Uppercase and lowercase characters.</small></span><input type="checkbox" name="password_require_mixed_case" <?= $settings['password_require_mixed_case']?'checked':'' ?>></label><label class="span-2 toggle-row"><span><strong>Require number</strong><small>At least one numeric character.</small></span><input type="checkbox" name="password_require_number" <?= $settings['password_require_number']?'checked':'' ?>></label><label class="span-2 toggle-row"><span><strong>Require symbol</strong><small>At least one special character.</small></span><input type="checkbox" name="password_require_symbol" <?= $settings['password_require_symbol']?'checked':'' ?>></label><div class="span-2"><button class="button primary" type="submit">Save security settings</button></div></form></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Current posture</span><h2>Security summary</h2></div></header><dl class="detail-list"><div><dt>Strong passwords</dt><dd><?= badge('enabled') ?></dd></div><div><dt>Login throttling</dt><dd><?= (int)$settings['login_attempt_limit'] ?> attempts</dd></div><div><dt>Lockout</dt><dd><?= (int)$settings['lockout_minutes'] ?> minutes</dd></div><div><dt>Session lifetime</dt><dd><?= (int)$settings['session_lifetime'] ?> minutes</dd></div><div><dt>Reset lifetime</dt><dd><?= (int)$settings['password_reset_lifetime'] ?> minutes</dd></div><div><dt>Open active sessions</dt><dd><?= count(array_filter(data_collection('sessions'),fn($s)=>$s['status']==='active')) ?></dd></div></dl><a class="button secondary full" href="<?= h(app_url('admin/sessions.php')) ?>">Manage sessions</a></section></div>
